function NavGroup({ group, active, select }: { group: NavGroupDefinition; active: string; select: (v: string) => void ;}) { const contains = group.modules.some(navModule => navModule.items.some(([name]) => name === active)), [open, setOpen] = useState(contains); const Icon = group.icon; return <section className="mb-2 overflow-hidden rounded-2xl border border-slate-200 bg-white"><button type="button" aria-expanded={open} onClick={() => setOpen(v => !v)} className={`focus-ring flex w-full items-center gap-3 p-3 text-left transition ${contains ? "bg-blue-50/70" : "hover:bg-slate-50"}`}><span className={`grid h-8 w-8 shrink-0 place-items-center rounded-xl ${contains ? "bg-blue-600 text-white" : "bg-slate-100 text-slate-500"}`}><Icon className="h-4 w-4" /></span><span className="min-w-0"><b className={`block text-[11px] leading-4 ${contains ? "text-blue-800" : "text-slate-700"}`}>{group.label}</b><small className="block truncate text-[9px] text-slate-400">{group.caption}</small></span><ChevronDown className={`ml-auto h-4 w-4 shrink-0 text-slate-400 transition-transform ${open ? "rotate-0" : "-rotate-90"}`} /></button>{open && <div className="border-t bg-slate-50/40 p-2">{group.modules.map(navModule => { const moduleContains = navModule.items.some(([name]) => name === active); return <Nav key={`${navModule.label}-${moduleContains}`} label={navModule.label} items={navModule.items} active={active} select={select} /> ;})}</div>}</section> ;}
function Nav({ label, items, active, select }: { label: string; items: NavItems; active: string; select: (v: string) => void ;}) { const contains = items.some(([n]) => n === active), [open, setOpen] = useState(contains); return <section className="mb-1"><button type="button" aria-expanded={open} onClick={() => setOpen(v => !v)} className={`flex w-full items-center rounded-xl px-3 py-2.5 text-left text-[10px] font-bold uppercase tracking-[.08em] transition ${contains ? "bg-white text-blue-700 shadow-sm" : "text-slate-500 hover:bg-white hover:text-slate-700"}`}><span>{label}</span><ChevronDown className={`ml-auto h-3.5 w-3.5 transition-transform ${open ? "rotate-0" : "-rotate-90"}`} /></button>{open && <div className="ml-3 border-l border-slate-200 pb-2 pl-2 pt-1">{items.map(([n, I]) => <button key={n} onClick={() => select(n)} className={`focus-ring mb-1 flex w-full items-center gap-2 rounded-xl px-2.5 py-2 text-left text-[12px] font-medium ${active === n ? "bg-blue-600 text-white shadow-sm" : "text-slate-600 hover:bg-white"}`}><I className="h-4 w-4 shrink-0" /><span className="min-w-0 flex-1 truncate">{n}</span>{n === "Asset intake & classification" && <span className={`rounded-full px-2 text-[9px] ${active === n ? "bg-white/20" : "bg-blue-100 text-blue-700"}`}>12</span>}{n === "Acquisition due diligence" && <span className={`rounded-full px-2 text-[9px] ${active === n ? "bg-white/20" : "bg-amber-100 text-amber-700"}`}>7</span>}{n === "Valuation review & approval" && <span className={`rounded-full px-2 text-[9px] ${active === n ? "bg-white/20" : "bg-violet-100 text-violet-700"}`}>9</span>}{n === "Applications" && <span className={`rounded-full px-2 text-[9px] ${active === n ? "bg-white/20" : "bg-rose-100 text-rose-700"}`}>42</span>}</button>)}</div>}</section> ;}
function Header({ active, menu, action, actionLabel, module }: { active: string; menu: () => void; action: () => void; actionLabel: string; module?: EnterpriseModule ;}) { const inventory = inventoryNav.some(([n]) => n === active), valuation = valuationNav.some(([n]) => n === active), marketing = marketingNav.some(([n]) => n === active), sale = saleNav.some(([n]) => n === active), lease = leaseNav.some(([n]) => n === active), jv = jvNav.some(([n]) => n === active), legal = legalNav.some(([n]) => n === active); return <header className="glass sticky top-0 z-20 flex h-[74px] items-center border-b px-4 sm:px-7 lg:px-9"><button onClick={menu} className="mr-3 rounded-xl border bg-white p-2 lg:hidden" aria-label="Open navigation"><Menu className="h-5 w-5" /></button><div><div className="text-xs text-slate-400">{module ? `${module.name} Workbench` : legal ? "Legal Documentation Management Workbench" : jv ? "Joint Venture Monitoring Workbench" : lease ? "Lease Management Workbench" : sale ? "Active Contracts (Sale) Workbench" : marketing ? "Marketing, Disposition & Revenue Workbench" : valuation ? "Valuation & Appraisal Workbench" : inventory ? "Asset Operations Workbench" : "Property Origination Workbench"}</div><h1 className="text-lg font-semibold">{active}</h1></div><div className="ml-auto flex gap-2"><button className="hidden items-center gap-2 rounded-xl border bg-white px-3 text-xs text-slate-500 shadow-sm sm:flex"><Search className="h-4 w-4" />Search IREMS <kbd className="ml-5 rounded border bg-slate-50 px-1.5">⌘ K</kbd></button><button aria-label="Notifications" className="rounded-xl border bg-white p-2.5"><Bell className="h-4 w-4" /></button><button onClick={action} className={`focus-ring flex items-center gap-2 rounded-xl px-3.5 py-2.5 text-xs font-semibold text-white shadow-lg ${module ? "bg-slate-900" : legal ? "bg-amber-700" : jv ? "bg-fuchsia-700" : lease ? "bg-teal-700" : sale ? "bg-cyan-700" : marketing ? "bg-rose-600" : valuation ? "bg-violet-600" : "bg-blue-600"}`}><Plus className="h-4 w-4" /><span className="hidden sm:inline">{actionLabel}</span></button></div></header> ;}
type BirthInsightKey = "active" | "approval" | "exceptions" | "completeness";
function Module({ active, items, query, filter, setQuery, setFilter, select, create }: { active: string; items: Property[]; query: string; filter: string; setQuery: (v: string) => void; setFilter: (v: string) => void; select: (p: Property) => void; create: () => void ;}) { const processCode = { "Asset intake & classification": "PIM-001", "Acquisition due diligence": "PIM-002", "Property baseline": "PIM-003", "Legacy migration": "PIM-004" }[active] as string | undefined; const [insight, setInsight] = useState<BirthInsightKey | null>(null); const insightCopy = insight ? { active: ["Active intakes", "Property birth records still moving through validation and acceptance."], approval: ["Ready for approval", "Complete intake records awaiting an authorized checker."], exceptions: ["Open exceptions", "Records with unresolved evidence, identity or control issues."], completeness: ["Baseline completeness", "Coverage of mandatory identity, title, tax, location and evidence fields."] }[insight] : null; const insightRows = insight === "approval" ? items.filter(p => p.status === "Ready for approval") : insight === "exceptions" ? items.filter(p => p.status === "Exception") : items.slice(0, 5); return <><div className="mb-7 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><div className="mb-2 text-xs font-bold uppercase tracking-[.1em] text-blue-600">● Module 01 · Property Birth</div><h2 className="text-3xl font-semibold tracking-[-.035em]">{active === "Birth overview" ? "Good morning, Ana." : active}</h2><p className="mt-1.5 text-sm text-slate-500">Establish a trusted property record from intake through controlled acceptance.</p></div><div className="flex items-center gap-2 rounded-xl border bg-white px-3 py-2 text-xs text-slate-500"><ShieldCheck className="h-4 w-4 text-emerald-600" />Compliance profile: GSIS Core v1.0</div></div>{active === "Birth overview" && <><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric icon={ListChecks} value="28" label="Active intakes" detail="12 need action" color="blue" onClick={() => setInsight("active")} /><Metric icon={CheckCircle2} value="6" label="Ready for approval" detail="₱412.8M total" color="emerald" onClick={() => setInsight("approval")} /><Metric icon={CircleAlert} value="4" label="Open exceptions" detail="2 past target" color="amber" onClick={() => setInsight("exceptions")} /><Metric icon={Gauge} value="84%" label="Baseline completeness" detail="+6% this month" color="violet" onClick={() => setInsight("completeness")} /></div><ReadinessBand /></>}<div className={`mt-5 grid gap-5 ${active === "Birth overview" ? "xl:grid-cols-[minmax(0,1fr)_340px]" : ""}`}>{processCode ? <BprExecution code={processCode}><Register {...{ items, query, filter, setQuery, setFilter, select, create }} compact={false} /></BprExecution> : <Register {...{ items, query, filter, setQuery, setFilter, select, create }} compact={active === "Birth overview"} />}{active === "Birth overview" && <Intelligence open={() => setInsight("exceptions")} />}</div>{insight && insightCopy && <OverviewThirdPane eyebrow="Property Birth insight" title={insightCopy[0]} description={insightCopy[1]} items={insightRows.map(p => ({ id: p.id, primary: p.name, secondary: `${p.id} · ${p.location}`, status: p.status, statusClass: styles[p.status], open: () => { setInsight(null); select(p) ;} }))} note="Counts are derived from versioned property-birth workflow states. Drill-down preserves authority, evidence, privacy and immutable audit context." close={() => setInsight(null)} />}</> ;}
function Metric({ icon: I, value, label, detail, color, onClick }: { icon: typeof Building2; value: string; label: string; detail: string; color: string; onClick?: () => void ;}) { const c: Record<string, string> = { blue: "bg-blue-50 text-blue-600", emerald: "bg-emerald-50 text-emerald-600", amber: "bg-amber-50 text-amber-600", violet: "bg-violet-50 text-violet-600" }; const content = <><div className={`grid h-9 w-9 place-items-center rounded-xl ${c[color]}`}><I className="h-[18px] w-[18px]" /></div><div className="mt-5 text-2xl font-semibold">{value}</div><div className="text-xs font-medium text-slate-600">{label}</div><div className="mt-2 flex items-center justify-between text-[11px] text-slate-400"><span>{detail}</span>{onClick && <span className="font-semibold text-blue-600">View →</span>}</div></>; return onClick ? <button type="button" aria-label={`View ${label}`} onClick={onClick} className="surface focus-ring rounded-[20px] border p-5 text-left transition hover:-translate-y-0.5 hover:border-blue-200 hover:shadow-lg">{content}</button> : <section className="surface rounded-[20px] border p-5">{content}</section> ;}
type OverviewInsightItem = { id: string; primary: string; secondary: string; status: string; statusClass: string; open: () => void ;};
function OverviewThirdPane({ eyebrow, title, description, items, note, close }: { eyebrow: string; title: string; description: string; items: OverviewInsightItem[]; note: string; close: () => void ;}) { return <><button aria-label={`Close ${title}`} className="fixed inset-0 z-40 bg-slate-950/20" onClick={close} /><aside role="dialog" aria-modal="true" aria-label={`${title} details`} className="fixed inset-y-0 right-0 z-50 w-full max-w-[540px] overflow-y-auto border-l bg-[#f8f9fb] shadow-2xl"><div className="glass sticky top-0 z-10 flex items-start border-b px-6 py-5"><div className="grid h-11 w-11 place-items-center rounded-2xl bg-blue-100 text-blue-700"><PanelsTopLeft className="h-5 w-5" /></div><div className="ml-3"><div className="text-[10px] font-bold uppercase tracking-wider text-blue-600">{eyebrow}</div><h2 className="text-lg font-semibold">{title}</h2><p className="mt-1 text-xs leading-5 text-slate-500">{description}</p></div><button onClick={close} className="ml-auto rounded-xl border bg-white p-2"><X className="h-4 w-4" /></button></div><div className="space-y-5 p-6"><Panel title="Related records">{items.map(item => <button key={item.id} onClick={item.open} className="flex w-full items-center gap-3 border-b py-3 text-left last:border-0"><span className="min-w-0"><b className="block truncate text-xs">{item.primary}</b><small className="text-slate-400">{item.secondary}</small></span><span className={`ml-auto shrink-0 rounded-full border px-2 py-1 text-[9px] font-semibold ${item.statusClass}`}>{item.status}</span></button>)}</Panel><div className="rounded-xl border border-blue-200 bg-blue-50 p-4 text-[11px] leading-5 text-blue-900">{note}</div></div></aside></> ;}
function Register({ items, query, filter, setQuery, setFilter, select, create, compact }: { items: Property[]; query: string; filter: string; setQuery: (v: string) => void; setFilter: (v: string) => void; select: (p: Property) => void; create: () => void; compact: boolean ;}) { const rows = compact ? items.slice(0, 5) : items; return <section className="surface overflow-hidden rounded-[22px] border"><div className="flex flex-col gap-3 border-b p-5 sm:flex-row sm:items-center"><div><h3 className="text-[15px] font-semibold">Property register</h3><p className="text-xs text-slate-400">Authoritative intake records</p></div><div className="ml-auto flex w-full gap-2 sm:w-auto"><label className="relative flex-1 sm:w-60"><Search className="absolute left-3 top-2.5 h-4 w-4 text-slate-400" /><input aria-label="Search properties" value={query} onChange={e => setQuery(e.target.value)} placeholder="Search ID, property…" className="focus-ring h-9 w-full rounded-xl border bg-slate-50 pl-9 pr-3 text-xs outline-none" /></label><select aria-label="Filter by status" value={filter} onChange={e => setFilter(e.target.value)} className="h-9 rounded-xl border bg-white px-3 text-xs"><option>All statuses</option><option>Ready for approval</option><option>For validation</option><option>Exception</option><option>Draft</option></select></div></div><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left"><thead><tr className="border-b bg-slate-50 text-[10px] uppercase tracking-wider text-slate-400"><th className="px-5 py-3">Property</th><th>Status</th><th>Completeness</th><th>Value</th><th>Owner</th></tr></thead><tbody>{rows.map(p => <tr key={p.id} onClick={() => select(p)} className="cursor-pointer border-b last:border-0 hover:bg-blue-50/40"><td className="px-5 py-4"><b className="text-[13px]">{p.name}</b><div className="mt-1 flex items-center gap-1 text-[11px] text-slate-400">{p.id} · <MapPin className="h-3 w-3" />{p.location}</div></td><td><span className={`rounded-full border px-2.5 py-1 text-[10px] font-semibold ${styles[p.status]}`}>{p.status}</span></td><td><div className="flex items-center gap-2"><i className="h-1.5 w-20 rounded-full bg-slate-100"><i className="block h-full rounded-full bg-blue-500" style={{ width: `${p.completion}%` }} /></i><small>{p.completion}%</small></div></td><td className="text-xs font-semibold">{p.value}</td><td><div className="text-xs">{p.owner}</div><small className="text-slate-400">{p.updated}</small></td></tr>)}</tbody></table></div>{!rows.length && <div className="p-10 text-center text-sm text-slate-500">No matching records.</div>}<div className="flex justify-between border-t bg-slate-50/50 px-5 py-3 text-[11px] text-slate-400"><span>{items.length} records shown</span><button onClick={create} className="font-semibold text-blue-600">Create intake</button></div></section> ;}
function Intelligence({ open }: { open?: () => void ;}) { return <div className="space-y-5"><section className="rounded-[22px] bg-gradient-to-br from-blue-600 to-indigo-700 p-5 text-white shadow-xl"><div className="flex justify-between text-xs font-semibold"><span className="flex gap-2"><Bot className="h-4 w-4" />IREMS Copilot</span><span className="rounded-full bg-white/15 px-2 py-1 text-[9px]">ADVISORY</span></div><h3 className="mt-5 text-lg font-semibold">3 records need attention</h3><p className="mt-2 text-xs leading-5 text-blue-100">Potential title annotation mismatch, a tax declaration variance, and one missing geotagged inspection photo.</p><button onClick={open} className="mt-5 flex w-full justify-center gap-2 rounded-xl bg-white py-2.5 text-xs font-semibold text-blue-700"><Sparkles className="h-4 w-4" />Review evidence</button><p className="mt-3 text-[10px] leading-4 text-blue-200">AI output is evidence-linked and confidence-scored. A human remains accountable.</p></section><section className="surface rounded-[22px] border p-5"><h3 className="flex gap-2 text-sm font-semibold"><Workflow className="h-4 w-4 text-blue-600" />Service readiness</h3>{["Property Registry API · v1", "Due Diligence service · v1", "Document service · event-linked", "AI Gateway · governed"].map(x => <div key={x} className="mt-3 flex items-center gap-2 text-[11px] text-emerald-700"><Check className="h-3 w-3" />{x}</div>)}<p className="mt-4 rounded-xl bg-slate-50 p-3 text-[10px] leading-4 text-slate-500">Versioned contracts and the outbox pattern allow each bounded context to split and scale independently.</p></section></div> ;}

function EnterpriseWorkbench({ module, active, select, create }: { module: EnterpriseModule; active: string; select: (record: EnterpriseRecord) => void; create: () => void ;}) { if (module.code === "MOB" || module.code === "OAN") return <ChannelProcessWorkbench module={module} active={active} select={select} create={create} />; const process = module.processes.find(p => p.nav === active); const role = enterpriseRole(module, active); return <><EnterpriseTitle module={module} active={active} /><EnterpriseRoleStrip module={module} active={active} />{active === module.overview && <EnterpriseOverview module={module} select={select} />} {process && <EnterpriseProcessView module={module} process={process} role={role} select={select} />} {process && <button onClick={create} className="mt-5 rounded-xl bg-slate-900 px-4 py-2.5 text-xs font-semibold text-white"><Plus className="mr-2 inline h-3.5 w-3.5" />{enterpriseActionLabel(module, active)}</button>}</> ;}
function EnterpriseTitle({ module, active }: { module: EnterpriseModule; active: string ;}) { const classification = ["ANL", "GOV", "INT", "PLT"].includes(module.code) ? "Enterprise control plane" : ["MOB", "OAN"].includes(module.code) ? "Digital operating channel" : "Financial operations"; return <div className="mb-5 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><div className="mb-2 text-xs font-bold uppercase tracking-[.1em] text-blue-700">● Module {module.number} · {module.name}</div><h2 className="text-3xl font-semibold tracking-[-.035em]">{active}</h2><p className="mt-1.5 max-w-3xl text-sm text-slate-500">{module.description}</p></div><div className="flex flex-col items-start gap-2 md:items-end"><span className="rounded-full border border-blue-200 bg-blue-50 px-3 py-1 text-[10px] font-bold uppercase tracking-wider text-blue-700">{classification}</span><div className="flex items-center gap-2 rounded-xl border bg-white px-3 py-2 text-xs text-slate-500"><ShieldCheck className="h-4 w-4 text-emerald-600" />{module.policy}</div></div></div> ;}
function EnterpriseRoleStrip({ module, active }: { module: EnterpriseModule; active: string ;}) { const current = enterpriseRole(module, active); return <section className="mb-5 grid gap-2 rounded-[20px] border bg-white p-3 sm:grid-cols-2 xl:grid-cols-4" aria-label="Operating model roles">{(["Configuration", "Operations", "Monitoring", "Governance"] as EnterpriseRole[]).map(role => { const count = module.processes.filter(p => enterpriseRole(module, p.nav) === role).length; const on = current === role; return <div key={role} className={`rounded-xl border p-3 transition ${on ? roleStyle[role] : "border-slate-100 bg-slate-50 text-slate-500"}`}><div className="flex items-center justify-between"><b className="text-xs">{role}</b><span className="rounded-full bg-white/70 px-2 py-0.5 text-[9px] font-bold">{count} view{count === 1 ? "" : "s"}</span></div><p className="mt-1 text-[10px] leading-4 opacity-80">{roleCopy[role]}</p></div> ;})}</section> ;}
function EnterpriseOverview({ module, select }: { module: EnterpriseModule; select: (record: EnterpriseRecord) => void ;}) { const [insight, setInsight] = useState<string | null>(null); const title = insight ?? "Related work"; return <><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{module.metrics.map(([value, label, detail, color], i) => <Metric key={label} icon={[module.icon, CheckCircle2, AlertTriangle, Sparkles][i]} value={value} label={label} detail={detail} color={color} onClick={() => setInsight(label)} />)}</div><ReadinessBand /><div className="mt-5 grid gap-5 xl:grid-cols-[minmax(0,1fr)_360px]"><div className="space-y-5"><EnterprisePipeline module={module} open={setInsight} /><EnterpriseRegister title="Controlled attention queue" subtitle="Configuration, operations, monitoring and governance items prioritized by risk" items={module.records} select={select} /></div><div className="space-y-5"><EnterpriseCopilot module={module} open={() => setInsight("AI review queue")} /><EnterpriseServiceCard module={module} /></div></div>{insight && <OverviewThirdPane eyebrow={`${module.code} control insight`} title={title} description={`Filtered ${module.name.toLowerCase()} records with source state, owner and next action.`} items={module.records.map(record => ({ id: record.id, primary: record.subject, secondary: `${record.id} · ${record.next}`, status: record.status, statusClass: enterpriseStyle[record.status], open: () => { setInsight(null); select(record) ;} }))} note={`Source: ${module.processes.map(p => p.code).join(", ")} · configuration and runtime records remain distinct. AI may prioritize and explain, but every material action requires an authorized human.`} close={() => setInsight(null)} />}</> ;}
function EnterprisePipeline({ module, open }: { module: EnterpriseModule; open: (label: string) => void ;}) { return <section className="surface rounded-[22px] border p-5"><div className="flex items-center justify-between"><div><h3 className="text-[15px] font-semibold">Controlled work pipeline</h3><p className="text-xs text-slate-400">Click a stage to inspect its queue without leaving the workbench</p></div><span className="rounded-full bg-blue-50 px-2.5 py-1 text-[11px] font-semibold text-blue-700">{module.records.length} priority records</span></div><div className="mt-6 grid grid-cols-2 gap-2 md:grid-cols-4">{module.pipeline.map(([name, count, color]) => <button key={name} type="button" onClick={() => open(`${name} stage`)} className={`rounded-xl p-3 text-left text-white transition hover:-translate-y-0.5 hover:shadow-md ${color}`}><b className="block text-xl">{count}</b><span className="text-[11px]">{name} →</span></button>)}</div></section> ;}
