function EnterpriseDrawer({ module, record, close }: { module: EnterpriseModule; record: EnterpriseRecord; close: () => void ;}) { const [tab, setTab] = useState("Record"), [action, setAction] = useState<"" | "returned" | "staged">(""); return <><button aria-label="Close record details" className="fixed inset-0 z-40 bg-slate-950/20" onClick={close} /><aside role="dialog" aria-modal="true" aria-label={`${record.subject} details`} className="fixed inset-y-0 right-0 z-50 w-full max-w-[720px] overflow-y-auto border-l bg-[#f8f9fb] shadow-2xl"><div className="glass sticky top-0 z-10 border-b px-6 py-5"><div className="flex items-start"><div className="grid h-11 w-11 place-items-center rounded-2xl bg-blue-100 text-blue-700"><module.icon className="h-5 w-5" /></div><div className="ml-3"><div className="text-[10px] font-bold uppercase tracking-wider text-blue-700">{module.code} · {record.id}</div><h2 className="text-lg font-semibold">{record.subject}</h2><p className="text-xs text-slate-500">{record.secondary} · {record.owner}</p></div><button onClick={close} className="ml-auto rounded-xl border bg-white p-2"><X className="h-4 w-4" /></button></div><div className="mt-5 flex gap-1 overflow-x-auto rounded-xl bg-slate-100 p-1">{["Record", "Controls", "Decision", "Evidence & DMS", "Events"].map(n => <button key={n} onClick={() => setTab(n)} className={`min-w-24 flex-1 rounded-lg px-2 py-2 text-[11px] font-semibold ${tab === n ? "bg-white shadow-sm" : "text-slate-500"}`}>{n}</button>)}</div></div><div className="space-y-5 p-6">{tab === "Record" && <Panel title="Authoritative record"><div className="grid gap-3 sm:grid-cols-2">{[["Status", record.status], ["Measure", record.measure], ["Risk", record.risk], ["Owner", record.owner], ["Next action", record.next], ["Service", module.service]].map(([k, v]) => <div key={k} className="rounded-xl border bg-white p-3"><small className="text-slate-400">{k}</small><b className="mt-1 block text-xs">{v}</b></div>)}</div></Panel>}{tab === "Controls" && <Panel title="Control evidence">{module.processes.map(p => <div key={p.code} className="mb-3 rounded-xl border bg-white p-3"><b className="text-xs">{p.code} · {p.title}</b><p className="mt-1 text-[11px] leading-5 text-slate-500">{p.outcome}</p></div>)}</Panel>}{tab === "Decision" && <Panel title="Human-accountable action"><p className="text-xs leading-5 text-slate-600">This demonstration stages a controlled request. It does not approve, post, notify, sign, file, disburse, foreclose or create an external commitment.</p>{!action ? <div className="mt-5 grid grid-cols-2 gap-2"><button onClick={() => setAction("returned")} className="rounded-xl border border-amber-300 bg-amber-50 py-2.5 text-xs font-semibold text-amber-800">Return with reason</button><button onClick={() => setAction("staged")} className="rounded-xl bg-slate-900 py-2.5 text-xs font-semibold text-white">Stage for checker</button></div> : <div className={`mt-5 rounded-xl p-3 text-xs ${action === "staged" ? "bg-emerald-50 text-emerald-800" : "bg-amber-50 text-amber-800"}`}>{action === "staged" ? "Staged with evidence references, actor, authority scope and timestamp." : "Returned with a reason-coded corrective task and retained history."}</div>}</Panel>}{tab === "Evidence & DMS" && <Panel title="Evidence references"><div className="rounded-xl border bg-white p-4 text-xs"><b className="block">External repository address</b><span className="mt-1 block break-all text-slate-500">dms://irems/{module.code.toLowerCase()}/{record.id}/evidence-set-v3</span><div className="mt-4 grid gap-2 sm:grid-cols-2"><span className="rounded-lg bg-slate-50 p-2">SHA-256 hash sealed</span><span className="rounded-lg bg-slate-50 p-2">Retention + hold evaluated</span><span className="rounded-lg bg-slate-50 p-2">Purpose-based access</span><span className="rounded-lg bg-slate-50 p-2">No document bytes in IREMS DB</span></div></div></Panel>}{tab === "Events" && <Panel title="Immutable domain events">{[[`${module.code}.CaseOpened.v1`, `18 Sep 2026 · ${record.owner}`], [`${module.code}.EvidenceLinked.v1`, "18 Sep 2026 · DMS adapter"], [`${module.code}.RiskAssessed.v1`, "18 Sep 2026 · Rules + human"], [`${module.code}.ActionDue.v1`, record.next]].map(([n, m]) => <div key={n} className="mt-4 flex gap-3"><i className="mt-1.5 h-2 w-2 rounded-full bg-blue-500" /><span><b className="block text-xs">{n}</b><small className="text-slate-400">{m}</small></span></div>)}</Panel>}</div></aside></> ;}
const intakeLibraries = { properties: ["Makati Commercial Lot", "Cebu Residential Estate", "Davao Warehouse Complex", "QC Condominium Portfolio", "Iloilo Agricultural Parcel", "Baguio Mixed-use Building"], regions: ["NCR", "CAR", "Region VI", "Region VII", "Region XI", "Enterprise-wide"], classifications: ["Public", "Internal", "Confidential", "Restricted", "Privileged"] };
