function loanActionLabel(active: string) { return active === "Origination" || active === "Loan overview" ? "New loan application" : active === "Credit & approval" ? "Open credit evaluation" : active === "Servicing & restructuring" ? "Open servicing action" : "Open collateral action" ;}
function LoanWorkbench({ module, active, select, create }: { module: EnterpriseModule; active: string; select: (record: EnterpriseRecord) => void; create: () => void ;}) { const process = loanProcessDesigns.find(p => p.nav === active); const controls = process ? module.processes.find(p => p.code === process.code)?.controls ?? [] : []; return <><LoanTitle active={active} />{active === "Loan overview" && <LoanOverview module={module} select={select} />}{process && <div className="space-y-5"><ControlledWorkflowRuntime key={process.code} process={process} controls={controls} /><LoanProcessView module={module} process={process} select={select} /></div>} {process && <button onClick={create} className="mt-5 rounded-xl bg-indigo-700 px-4 py-2.5 text-xs font-semibold text-white"><Plus className="mr-2 inline h-3.5 w-3.5" />{loanActionLabel(active)}</button>}</> ;}
function LoanTitle({ active }: { active: string ;}) { return <div className="mb-7 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><div className="mb-2 text-xs font-bold uppercase tracking-[.1em] text-indigo-700">● Core IREMS · Module 15 · Loan Management</div><h2 className="text-3xl font-semibold tracking-[-.035em]">{active}</h2><p className="mt-1.5 max-w-3xl text-sm text-slate-500">BPR-driven housing-loan lifecycle from controlled application intake through human credit decision, servicing, restructuring, collateral release or legally gated foreclosure.</p></div><div className="flex flex-col items-start gap-2 md:items-end"><span className="rounded-full border border-indigo-200 bg-indigo-50 px-3 py-1 text-[10px] font-bold uppercase tracking-wider text-indigo-700">4 Level 4 processes · 24 controlled activities</span><div className="flex items-center gap-2 rounded-xl border bg-white px-3 py-2 text-xs text-slate-500"><ShieldCheck className="h-4 w-4 text-emerald-600" />GSIS credit + collateral profile v1.0</div></div></div> ;}
function LoanOverview({ module, select }: { module: EnterpriseModule; select: (record: EnterpriseRecord) => void ;}) { const [insight, setInsight] = useState<string | null>(null); return <><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric icon={FileText} value="74" label="Applications in process" detail="₱1.28B requested" color="blue" onClick={() => setInsight("Application pipeline")} /><Metric icon={Scale} value="18" label="Credit decisions due" detail="4 enhanced review" color="emerald" onClick={() => setInsight("Credit approval queue")} /><Metric icon={Receipt} value="31" label="Servicing attention" detail="₱86.4M exposure" color="amber" onClick={() => setInsight("Servicing and remedy queue")} /><Metric icon={Landmark} value="12" label="Collateral actions" detail="3 legal gates" color="violet" onClick={() => setInsight("Collateral control queue")} /></div><ReadinessBand /><div className="mt-5 grid gap-5 xl:grid-cols-[minmax(0,1fr)_360px]"><div className="space-y-5"><LoanLifecycle open={setInsight} /><EnterpriseRegister title="Loan attention queue" subtitle="Applications, decisions, accounts and collateral actions prioritized by SLA, value and control risk" items={module.records} select={select} /></div><div className="space-y-5"><LoanCopilot open={() => setInsight("AI-assisted review")} /><LoanServiceCard /></div></div>{insight && <OverviewThirdPane eyebrow="LOA portfolio insight" title={insight} description="BPR-traced loan records with accountable owner, next action and current control state." items={module.records.map(record => ({ id: record.id, primary: record.subject, secondary: `${record.id} · ${record.next}`, status: record.status, statusClass: enterpriseStyle[record.status], open: () => { setInsight(null); select(record) ;} }))} note="Source: LOA-001 to LOA-004. AI can prioritize, extract and recommend only; approval, restructuring, foreclosure, release and accounting consequences remain human-authorized." close={() => setInsight(null)} />}</> ;}
function LoanLifecycle({ open }: { open: (title: string) => void ;}) { const stages = [["LOA-001", "Origination", "74", "Complete file"], ["LOA-002", "Credit decision", "18", "Human approval"], ["LOA-003", "Servicing", "684", "Ledger + remedy"], ["LOA-004", "Collateral", "12", "Legal gate"]]; return <section className="surface rounded-[22px] border p-5"><div className="flex items-center justify-between"><div><h3 className="text-[15px] font-semibold">BPR loan lifecycle</h3><p className="text-xs text-slate-400">Each stage opens its traceable queue; no process is implied or skipped</p></div><span className="rounded-full bg-indigo-50 px-2.5 py-1 text-[11px] font-semibold text-indigo-700">QS-FR-15.1–15.4</span></div><div className="mt-6 grid gap-2 md:grid-cols-4">{stages.map(([code, name, count, gate], i) => <button key={code} type="button" onClick={() => open(`${code} · ${name}`)} className="rounded-xl border border-indigo-100 bg-indigo-50 p-3 text-left transition hover:-translate-y-0.5 hover:border-indigo-300 hover:shadow-md"><div className="flex items-center justify-between"><b className="text-[10px] text-indigo-700">{code}</b><span className="text-lg font-semibold text-indigo-950">{count}</span></div><span className="mt-2 block text-xs font-semibold">{name}</span><small className="mt-1 block text-slate-500">Gate: {gate}</small><div className="mt-3 h-1 rounded-full bg-indigo-100"><div className="h-full rounded-full bg-indigo-600" style={{ width: `${58 + i * 12}%` }} /></div></button>)}</div></section> ;}
function LoanProcessView({ module, process, select }: { module: EnterpriseModule; process: LoanProcessDesign; select: (record: EnterpriseRecord) => void ;}) { const controls = module.processes.find(p => p.code === process.code)?.controls ?? []; const items = module.records.filter(record => process.records.includes(record.id)); return <div className="space-y-5"><section className="grid gap-3 md:grid-cols-3"><div className="rounded-[20px] border bg-white p-4"><small className="font-bold uppercase tracking-wider text-indigo-600">Trigger</small><p className="mt-2 text-xs font-semibold leading-5">{process.trigger}</p></div><div className="rounded-[20px] border bg-white p-4"><small className="font-bold uppercase tracking-wider text-emerald-600">Required output</small><p className="mt-2 text-xs font-semibold leading-5">{process.output}</p></div><div className="rounded-[20px] border bg-white p-4"><small className="font-bold uppercase tracking-wider text-violet-600">Decision chain</small><p className="mt-2 text-xs font-semibold leading-5">{process.owner}</p></div></section><section className="surface overflow-hidden rounded-[22px] border"><div className="border-b p-5"><div className="text-[10px] font-bold uppercase tracking-widest text-indigo-700">{process.code} · Level 4 controlled flow</div><h3 className="mt-1 text-[15px] font-semibold">Six-step BPR execution</h3><p className="text-xs text-slate-400">Every activity produces attributable evidence and preserves the submitted or approved version.</p></div><div className="grid gap-px bg-slate-200 lg:grid-cols-6">{process.steps.map(([step, actor, instruction]) => <div key={step} className="bg-white p-4"><b className="text-[11px] text-indigo-700">{step}</b><span className="mt-2 block text-[10px] font-semibold text-slate-500">{actor}</span><p className="mt-2 text-[11px] leading-5 text-slate-600">{instruction}</p></div>)}</div></section><div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_360px]"><EnterpriseRegister title={`${process.code} operational queue`} subtitle={`Current records governed by ${process.form}, ${process.checklist} and ${process.register}`} items={items} select={select} /><div className="space-y-5"><ControlCard icon={ShieldCheck} title="BPR mandatory controls" rows={controls} /><section className="surface rounded-[22px] border p-5"><h3 className="text-sm font-semibold">Forms, controls and assurance</h3>{[[process.form, "Versioned request / case form"], [process.checklist, "System-generated checklist; reviewer signs"], [process.register, "Exception, escalation and resolution register"], [`RPT-${process.code}-01`, "Operations dashboard and SLA ageing"], [`UAT-${process.code}-01..04`, "Positive, control and recovery acceptance"]].map(([id, name]) => <div key={id} className="mt-3 rounded-xl bg-slate-50 p-3"><b className="block text-[10px] text-indigo-700">{id}</b><span className="text-[11px] text-slate-600">{name}</span></div>)}</section><section className="rounded-[20px] border border-amber-200 bg-amber-50 p-4"><div className="flex items-center gap-2 text-xs font-semibold text-amber-900"><CircleAlert className="h-4 w-4" />Legal and regulatory applicability</div><p className="mt-2 text-[11px] leading-5 text-amber-800">FCP, CIC, AML, foreclosure/redemption and BSP ROPA profiles are conditional until GSIS Legal/Compliance approves applicability, rule version, evidence and effective date. Core privacy, records, security, authority and audit controls remain active.</p></section></div></div></div> ;}
function LoanCopilot({ open }: { open: () => void ;}) { return <section className="overflow-hidden rounded-[22px] border border-indigo-200 bg-gradient-to-br from-indigo-700 to-slate-950 p-5 text-white shadow-xl"><div className="flex items-center justify-between"><span className="flex items-center gap-2 text-xs font-semibold"><Bot className="h-4 w-4" />Loan Decision Copilot</span><span className="rounded-full bg-white/10 px-2 py-1 text-[9px] font-bold">ADVISORY</span></div><h3 className="mt-5 text-lg font-semibold">9 cases need human review</h3><p className="mt-2 text-xs leading-5 text-indigo-100">Affordability variance, document inconsistency and payment-pattern signals are linked to source evidence and policy version.</p><button onClick={open} className="mt-5 w-full rounded-xl bg-white py-2.5 text-xs font-semibold text-indigo-800">Review evidence and confidence</button><p className="mt-3 text-[10px] leading-4 text-indigo-200">AI cannot approve or decline credit, change terms, restructure an account, foreclose, release collateral or post accounting entries.</p></section> ;}
