function JvAi({ open }: { open: (v: JvInsightKey) => void ;}) { const findings = [["Milestone delay pattern", "94%", "ai_delay"], ["Revenue-share variance", "89%", "ai_variance"], ["Related-party evidence gap", "83%", "ai_conflict"]] as const; return <section className="overflow-hidden rounded-[22px] border border-fuchsia-200 bg-gradient-to-br from-fuchsia-800 to-slate-950 p-5 text-white shadow-xl"><div className="flex items-center justify-between"><span className="flex items-center gap-2 text-xs font-semibold"><Bot className="h-4 w-4" />JV Performance Copilot</span><span className="rounded-full bg-white/10 px-2 py-1 text-[9px] font-bold">ADVISORY</span></div><h3 className="mt-5 text-lg font-semibold">6 projects need review</h3><p className="mt-2 text-xs leading-5 text-fuchsia-100">Evidence-grounded signals prioritize delivery slippage, sharing variances and governance evidence gaps.</p><div className="mt-4 space-y-2 text-[11px]">{findings.map(([label, score, key]) => <button type="button" key={key} onClick={() => open(key)} className="focus-ring block w-full rounded-xl bg-white/10 p-3 text-left transition hover:bg-white/20">{label}<b className="float-right">{score} →</b></button>)}</div><p className="mt-4 text-[10px] leading-4 text-fuchsia-200">AI cannot approve a partner, alter agreement terms, post shares, accept a milestone, declare default, or approve exit/buyout.</p></section> ;}
