function JvInsight({ insight, close, select }: { insight: JvInsightKey; close: () => void; select: (v: JvProject) => void ;}) { const copy: Record<JvInsightKey, [string, string]> = { projects: ["Active JV projects", "Registered and approved projects under Joint Venture Management."], milestones: ["Milestones due", "Development, turnover, permit and inspection milestones requiring action."], share: ["GSIS share due", "Contribution and distribution events expected within 30 days."], risk: ["High-risk reviews", "Projects crossing performance, compliance or authority thresholds."], registered: ["Registered JVs", "JVM-001 agreements, partners, terms and governance calendars."], delivery: ["Delivery watch", "JVM-002 milestone and developer-compliance attention queue."], ledger: ["Ledger review", "JVM-003 contribution, cost and revenue-sharing reconciliations."], exit: ["Exit and buyout", "JVM-004 performance, recovery, exit and buyout cases."], ai_delay: ["Milestone delay signal", "Evidence behind Copilot delivery-risk recommendations."], ai_variance: ["Revenue-share variance", "Agreement-versus-ledger differences requiring Finance review."], ai_conflict: ["Related-party evidence gaps", "Conflict-of-interest, beneficial-ownership or procurement evidence for human review."] }; const rows = insight === "milestones" || insight === "delivery" || insight === "ai_delay" ? jvSeed.filter(x => x.status === "Milestone overdue" || x.status === "Compliance action") : insight === "share" || insight === "ledger" || insight === "ai_variance" ? jvSeed.filter(x => x.status === "Ledger review" || x.status === "Active") : insight === "risk" || insight === "exit" ? jvSeed.filter(x => x.risk === "High" || x.status === "Exit planning" || x.status === "Executive review") : insight === "ai_conflict" ? jvSeed.filter(x => x.risk !== "Low") : jvSeed; return <OverviewThirdPane eyebrow="Joint venture insight" title={copy[insight][0]} description={copy[insight][1]} items={rows.map(x => ({ id: x.id, primary: x.project, secondary: `${x.partner} · ${x.nextMilestone}`, status: x.status, statusClass: jvStyle[x.status], open: () => { close(); select(x) ;} }))} note="Figures link to JVM-001–JVM-004 records. AI is evidence-linked and advisory; authorized GSIS officers retain partner, milestone, ledger, recovery and exit decisions." close={close} /> ;}

