function InspectionModal({ close, complete }: { close: () => void; complete: (name: string) => void ;}) { const [asset, setAsset] = useState(inventorySeed[2].name), [date, setDate] = useState("2026-09-22"), [scope, setScope] = useState("Full physical verification"); return <><button aria-label="Close inspection form" className="fixed inset-0 z-40 bg-slate-950/25" onClick={close} /><div role="dialog" aria-modal="true" aria-labelledby="inspection-title" className="fixed left-1/2 top-1/2 z-50 w-[calc(100%-32px)] max-w-lg -translate-x-1/2 -translate-y-1/2 rounded-[24px] border bg-white p-6 shadow-2xl"><div className="flex"><div><div className="text-[10px] font-bold uppercase tracking-wider text-indigo-600">Module 02 workflow</div><h2 id="inspection-title" className="mt-1 text-xl font-semibold">Schedule inspection</h2><p className="mt-1 text-xs text-slate-500">Creates an assigned, evidence-required inspection task.</p></div><button onClick={close} className="ml-auto h-9 rounded-xl border p-2"><X className="h-4 w-4" /></button></div><form className="mt-6 space-y-4" onSubmit={e => { e.preventDefault(); complete(asset) ;}}><Label text="Property"><select value={asset} onChange={e => setAsset(e.target.value)} className="h-11 w-full rounded-xl border bg-white px-3 text-sm">{inventorySeed.map(a => <option key={a.id}>{a.name}</option>)}</select></Label><Label text="Target date"><input type="date" required value={date} onChange={e => setDate(e.target.value)} className="h-11 w-full rounded-xl border bg-slate-50 px-3 text-sm" /></Label><Label text="Inspection scope"><select value={scope} onChange={e => setScope(e.target.value)} className="h-11 w-full rounded-xl border bg-white px-3 text-sm"><option>Full physical verification</option><option>Condition follow-up</option><option>Occupancy validation</option><option>Custody confirmation</option></select></Label><div className="rounded-xl bg-indigo-50 p-3 text-[11px] leading-5 text-indigo-800">Required evidence: geotagged photos, inspector attestation, condition rating and occupancy observation.</div><div className="flex justify-end gap-2 pt-2"><button type="button" onClick={close} className="rounded-xl border px-4 py-2.5 text-xs font-semibold">Cancel</button><button className="rounded-xl bg-indigo-600 px-4 py-2.5 text-xs font-semibold text-white">Create inspection task</button></div></form></div></> ;}

function Drawer({ property, close }: { property: Property; close: () => void ;}) {
const [tab, setTab] = useState("Baseline"), [checks, setChecks] = useState([true, true, false, true]); return <><button aria-label="Close details" className="fixed inset-0 z-40 bg-slate-950/20" onClick={close} /><aside role="dialog" aria-modal="true" aria-label={`${property.name} details`} className="fixed inset-y-0 right-0 z-50 w-full max-w-[620px] overflow-y-auto border-l bg-[#f8f9fb] shadow-2xl"><div className="glass sticky top-0 z-10 border-b px-6 py-5"><div className="flex items-start"><div className="grid h-11 w-11 place-items-center rounded-2xl bg-blue-100 text-blue-700"><Building2 className="h-5 w-5" /></div><div className="ml-3"><div className="text-[10px] font-bold uppercase tracking-wider text-blue-600">{property.id}</div><h2 className="text-lg font-semibold">{property.name}</h2><p className="text-xs text-slate-500">{property.location}</p></div><button onClick={close} className="ml-auto rounded-xl border bg-white p-2"><X className="h-4 w-4" /></button></div><div className="mt-5 flex gap-1 rounded-xl bg-slate-100 p-1">{["Baseline", "Due diligence", "Documents", "Timeline"].map(n => <button key={n} onClick={() => setTab(n)} className={`flex-1 rounded-lg px-2 py-2 text-[11px] font-semibold ${tab === n ? "bg-white shadow-sm" : "text-slate-500"}`}>{n}</button>)}</div></div><div className="p-6">
    {tab === "Baseline" && <div className="space-y-5"><Panel title="Core identity"><div className="grid grid-cols-2 gap-4"><Field l="Asset class" v={property.type} /><Field l="Indicative value" v={property.value} /><Field l="Record steward" v={property.owner} /><Field l="Completeness" v={`${property.completion}%`} /></div></Panel><Panel title="Identifiers & location"><div className="grid grid-cols-2 gap-4"><Field l="TCT / CCT" v="TCT-0069281" /><Field l="Tax declaration" v="TD-14-009-771" /><Field l="Lot / block" v="Lot 18 · Block 4" /><Field l="Coordinates" v="14.5547, 121.0244" /></div></Panel></div>}
    {tab === "Due diligence" && <Panel title="Acceptance controls"><p className="text-xs text-slate-500">Evidence-gated checklist · 3 of 4 passed</p><div className="mt-5 space-y-3">{[["Ownership and authority verified", "CMP-GOV-002"], ["Title and encumbrances checked", "CMP-REA-001"], ["Tax status reconciled", "CMP-REA-007"], ["Personal data minimized", "PIM-002"]].map(([l, c], i) => <button key={c} onClick={() => setChecks(x => x.map((v, n) => n === i ? !v : v))} className="flex w-full items-center gap-3 rounded-xl border bg-white p-3 text-left"><span className={`grid h-5 w-5 place-items-center rounded-md border ${checks[i] ? "border-emerald-500 bg-emerald-500 text-white" : ""}`}>{checks[i] && <Check className="h-3.5 w-3.5" />}</span><span><b className="block text-xs">{l}</b><small className="text-slate-400">{c} · evidence retained</small></span></button>)}</div><div className="mt-5 rounded-xl border border-amber-200 bg-amber-50 p-3 text-[10px] leading-4 text-amber-800"><b>BSP ROPA profile:</b> conditional benchmark only; mandatory when GSIS Legal/Compliance activates it for an applicable asset or transaction.</div></Panel>}
    {tab === "Documents" && <Panel title="Evidence vault">{["Transfer Certificate of Title.pdf", "Tax Declaration 2026.pdf", "Geotagged Inspection Set.zip"].map((n, i) => <div key={n} className="mt-3 flex items-center gap-3 rounded-xl border p-3"><FileText className="h-5 w-5 text-blue-600" /><span><b className="block text-xs">{n}</b><small className="text-slate-400">SHA-256 sealed · version {i + 1}</small></span><ShieldCheck className="ml-auto h-4 w-4 text-emerald-600" /></div>)}</Panel>}
    {tab === "Timeline" && <Panel title="Immutable activity">{[["Baseline enriched", "Ana Santos · 18 Sep, 09:42"], ["Title evidence verified", "Marco Reyes · 17 Sep, 15:18"], ["Intake record created", "System · 16 Sep, 11:03"]].map(([n, m]) => <div key={n} className="mt-5 flex gap-3"><i className="mt-1.5 h-2 w-2 rounded-full bg-blue-500" /><span><b className="block text-xs">{n}</b><small className="text-slate-400">{m}</small></span></div>)}</Panel>}
  </div></aside></>
;}
function Panel({ title, children }: { title: string; children: React.ReactNode ;}) { return <section className="surface rounded-2xl border p-5"><h3 className="mb-4 text-sm font-semibold">{title}</h3>{children}</section> ;}; function Field({ l, v }: { l: string; v: string ;}) { return <div><div className="text-[10px] uppercase tracking-wider text-slate-400">{l}</div><b className="mt-1 block text-xs text-slate-700">{v}</b></div> ;}
function Create({close,submit}:{close:()=>void;submit:(v:{name:string;location:string;type:string})=>void}){const[name,setName]=useState(""),[location,setLocation]=useState("Makati City, NCR"),[type,setType]=useState("Commercial land");return <><button aria-label="Close intake" className="fixed inset-0 z-40 bg-slate-950/25" onClick={close}/><div role="dialog" aria-modal="true" aria-labelledby="new-property" className="fixed left-1/2 top-1/2 z-50 w-[calc(100%-32px)] max-w-lg -translate-x-1/2 -translate-y-1/2 rounded-[24px] border bg-white p-6 shadow-2xl"><div className="flex"><div><div className="text-[10px] font-bold uppercase tracking-wider text-blue-600">Controlled intake</div><h2 id="new-property" className="mt-1 text-xl font-semibold">Create property birth record</h2><p className="mt-1 text-xs text-slate-500">Location and asset class use effective-dated master libraries.</p></div><button onClick={close} className="ml-auto h-9 rounded-xl border p-2"><X className="h-4 w-4"/></button></div><form className="mt-6 space-y-4" onSubmit={e=>{e.preventDefault();if(name.trim())submit({name:name.trim(),location,type})}}><Label text="Property name"><input required value={name} onChange={e=>setName(e.target.value)} placeholder="e.g. Pasig Office Building" className="h-11 w-full rounded-xl border bg-slate-50 px-3 text-sm"/></Label><Label text="Location hierarchy"><select value={location} onChange={e=>setLocation(e.target.value)} className="h-11 w-full rounded-xl border bg-white px-3 text-sm">{["Makati City, NCR","Quezon City, NCR","Cebu City, Region VII","Davao City, Region XI","Pavia, Iloilo, Region VI","Baguio City, CAR"].map(x=><option key={x}>{x}</option>)}</select></Label><Label text="Initial asset class"><select value={type} onChange={e=>setType(e.target.value)} className="h-11 w-full rounded-xl border bg-white px-3 text-sm">{["Commercial land","Residential","Industrial","Condominium","Agricultural","Mixed use"].map(x=><option key={x}>{x}</option>)}</select></Label><ReferenceDataNotice/><div className="flex justify-end gap-2 pt-2"><button type="button" onClick={close} className="rounded-xl border px-4 py-2.5 text-xs font-semibold">Cancel</button><button className="rounded-xl bg-blue-600 px-4 py-2.5 text-xs font-semibold text-white">Create draft record</button></div></form></div></>}
