function Admin({section}:{section:string}){const d=adminInfo[section],I=d.icon;const[detail,setDetail]=useState<string|null>(null),[staged,setStaged]=useState(false);return <><div className="mb-7 flex items-center gap-4"><div className="grid h-12 w-12 place-items-center rounded-2xl bg-blue-100 text-blue-700"><I className="h-5 w-5"/></div><div><div className="text-[10px] font-bold uppercase tracking-wider text-blue-600">Platform administration</div><h2 className="text-3xl font-semibold">{section}</h2><p className="mt-1 text-sm text-slate-500">{d.sub}</p></div></div><div className="grid gap-3 sm:grid-cols-3">{d.metrics.map(([l,v])=><button key={l} onClick={()=>{setDetail(l);setStaged(false)}} className="surface rounded-[20px] border p-5 text-left transition hover:-translate-y-0.5 hover:border-blue-200 hover:shadow-lg"><b className="text-2xl">{v}</b><div className="mt-1 flex items-center justify-between text-xs text-slate-500"><span>{l}</span><span className="font-semibold text-blue-600">View →</span></div></button>)}</div><section className="surface mt-5 rounded-[22px] border"><div className="flex items-center border-b p-5"><div><h3 className="text-sm font-semibold">{section} register</h3><p className="text-xs text-slate-400">Policy-controlled configuration · click any record</p></div><button onClick={()=>{setDetail("Add controlled record");setStaged(false)}} className="ml-auto flex gap-2 rounded-xl bg-blue-600 px-3 py-2 text-xs font-semibold text-white"><Plus className="h-4 w-4"/>Add record</button></div>{d.rows.map(([n,x,s])=><button key={n} onClick={()=>{setDetail(n);setStaged(false)}} className="grid w-full grid-cols-[minmax(0,1fr)_140px_100px] border-b px-5 py-4 text-left text-xs last:border-0 hover:bg-blue-50/40"><b>{n}</b><span className="text-slate-500">{x}</span><b className="text-right text-emerald-700">{s} →</b></button>)}</section><div className="mt-5 grid gap-4 md:grid-cols-3"><Arch icon={Workflow} title="Microservice-ready" text="Bounded context, versioned API contract, event outbox, and independent scaling boundary."/><Arch icon={Sparkles} title="AI-enabled" text="Governed gateway, evidence grounding, confidence score, human decision, and complete trace."/><Arch icon={ShieldCheck} title="Compliance by design" text="Purpose, legal basis, access, retention, and audit evidence embedded in workflow."/></div>{detail&&<><button aria-label="Close administration details" className="fixed inset-0 z-40 bg-slate-950/20" onClick={()=>setDetail(null)}/><aside role="dialog" aria-modal="true" aria-label={`${detail} administration details`} className="fixed inset-y-0 right-0 z-50 w-full max-w-[540px] overflow-y-auto border-l bg-[#f8f9fb] shadow-2xl"><div className="glass sticky top-0 z-10 flex items-start border-b px-6 py-5"><div className="grid h-11 w-11 place-items-center rounded-2xl bg-blue-100 text-blue-700"><I className="h-5 w-5"/></div><div className="ml-3"><div className="text-[10px] font-bold uppercase tracking-wider text-blue-600">{section} control</div><h2 className="text-lg font-semibold">{detail}</h2><p className="mt-1 text-xs text-slate-500">Effective-dated, maker-checker controlled and fully audited.</p></div><button onClick={()=>setDetail(null)} className="ml-auto rounded-xl border bg-white p-2"><X className="h-4 w-4"/></button></div><div className="space-y-5 p-6"><Panel title="Governed change"><div className="space-y-3">{["Change purpose and accountable owner","Effective date and downstream impact","Segregation-of-duties validation","Approval, deployment and rollback evidence"].map(x=><div key={x} className="flex items-center gap-3 rounded-xl border bg-white p-3 text-xs"><CheckCircle2 className="h-4 w-4 text-emerald-600"/>{x}</div>)}</div>{section==="Master data"&&<div className="mt-4"><Label text="Reference library"><select className="h-11 w-full rounded-xl border bg-white px-3 text-sm"><option>Property and asset classifications</option><option>Location hierarchy</option><option>Application and product types</option><option>Workflow and status codes</option><option>Accounting and tax mappings</option></select></Label><div className="mt-3"><ReferenceDataNotice/></div></div>}<button onClick={()=>setStaged(true)} className="mt-5 w-full rounded-xl bg-blue-600 py-2.5 text-xs font-semibold text-white">Stage maker-checker request</button>{staged&&<div className="mt-3 rounded-xl bg-emerald-50 p-3 text-xs text-emerald-800">Change request staged with impact, effective date and immutable audit reference.</div>}</Panel></div></aside></>}</>}
function Arch({ icon: I, title, text }: { icon: typeof Building2; title: string; text: string ;}) { return <div className="surface rounded-2xl border p-4"><b className="flex items-center gap-2 text-xs"><I className="h-4 w-4 text-blue-600" />{title}</b><p className="mt-2 text-[11px] leading-5 text-slate-500">{text}</p></div> ;}
